import {ToolRegistry} from './registry.js';
import type {ToolDefinition} from '../../types/ai.js';
import Ajv from 'ajv';
import {jest} from '@jest/globals';

describe('ToolRegistry', () => {
  describe('execute', () => {
    it('unit test rejects input missing a required property with a ToolResponse and never calls the executor', async () => {
      const registry = new ToolRegistry();
      let executorCalls = 0;
      const definition: ToolDefinition = {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      };
      registry.register(definition, async () => {
        executorCalls += 1;
        return 'sunny';
      });

      const response = await registry.execute('get_weather', {});

      expect({calls: executorCalls, result: response.result}).toEqual({
        calls: 0,
        result: expect.stringMatching(/required.*location|missingProperty.*location|location.*required/i),
      });
    });

    it('passes valid input with an unlisted extra property to the executor unchanged', async () => {
      const registry = new ToolRegistry();
      let capturedInput: any;
      let calls = 0;
      registry.register(
        {
          name: 'test_extra',
          description: 'test',
          inputSchema: {
            type: 'object',
            properties: {a: {type: 'string'}},
          },
        },
        async input => {
          calls++;
          capturedInput = input;
          return 'ok';
        }
      );
      const input = {a: 'val', extra: 123};
      await registry.execute('test_extra', input);
      expect(calls).toBe(1);
      expect(capturedInput).toEqual(input);
    });

    it('rejects a wrong-typed field with a message naming the field path and the expected type, and that the message does not contain the offending value', async () => {
      const registry = new ToolRegistry();
      registry.register(
        {
          name: 'test_type',
          description: 'test',
          inputSchema: {
            type: 'object',
            properties: {location: {type: 'string'}},
          },
        },
        async () => 'ok'
      );

      const response = await registry.execute('test_type', {location: 123456789});
      expect(response.result).toMatch(/location/);
      expect(response.result).toMatch(/string/);
      expect(response.result).not.toMatch(/123456789/);
    });

    it('throws at registration time for an uncompilable schema naming the tool', () => {
      const registry = new ToolRegistry();
      expect(() => {
        registry.register(
          {
            name: 'broken_tool',
            description: 'test',
            inputSchema: {
              type: 'object',
              properties: {a: {type: 'not-a-type'}},
            },
          },
          async () => 'ok'
        );
      }).toThrow(/broken_tool/);
    });

    it('validates a function-valued tool definition against the schema current at that call, not a stale cached one', async () => {
      const registry = new ToolRegistry();
      let schemaRef: any = {type: 'object', properties: {a: {type: 'string'}}, required: ['a']};
      registry.register(
        () => ({
          name: 'dynamic',
          description: 'test',
          inputSchema: schemaRef,
        }),
        async () => 'ok'
      );

      let res1 = await registry.execute('dynamic', {a: 'val'});
      expect(res1.result).toBe('ok');

      schemaRef = {type: 'object', properties: {b: {type: 'number'}}, required: ['b']};
      let res2 = await registry.execute('dynamic', {a: 'val'});
      expect(res2.result).toMatch(/Validation failed.*b/);
    });

    it("compiles a static tool's schema once across ten execute calls", async () => {
      const compileSpy = jest.spyOn(Ajv.prototype, 'compile');
      const registry = new ToolRegistry();
      registry.register(
        {
          name: 'static_tool',
          description: 'test',
          inputSchema: {type: 'object', properties: {a: {type: 'string'}}},
        },
        async () => 'ok'
      );

      const startCount = compileSpy.mock.calls.length;
      for (let i = 0; i < 10; i++) {
        await registry.execute('static_tool', {a: 'test'});
      }
      expect(compileSpy.mock.calls.length - startCount).toBe(0);
      compileSpy.mockRestore();
    });
  });
});

